def test_artnet_macrumors_quillette_feeds_live_http_200():
    """Hit the three batch81 feeds with the same headers fetch_source sends (not stubs)."""
    by_id = {s.id: s for s in SOURCES}
    for source_id in _ARTNET_MACRUMORS_QUILLETTE_PRIMARY:
        source = by_id[source_id]
        request = urllib.request.Request(source.feed_url, headers=RSS_HEADERS)
        try:
            with urllib.request.urlopen(request, timeout=30) as resp:
                status = resp.status
                body = resp.read()
        except urllib.error.HTTPError as exc:
            raise AssertionError(
                f"{source_id} {source.feed_url} HTTP {exc.code} with RSS_HEADERS"
            ) from exc
        assert status == 200, f"{source_id} HTTP {status}"
        assert body, f"{source_id} empty body"
        root = ET.fromstring(_decode_feed_body(body))
        items = _feed_items(root)
        count = len(items)
        assert count > 0, f"{source_id} parsed 0 items (bytes={len(body)})"
        # Required: parseable title / url / published on each item.
        # RSS 2.0 (artnet / macrumors /
        # quillette) uses the un-namespaced
        # element text.
        for i, item in enumerate(items):
            title = _item_title(item)
            url = _item_link(item)
            published = _item_published(item)
            assert title, f"{source_id} item[{i}] missing title"
            assert url, f"{source_id} item[{i}] missing url"
            assert published, f"{source_id} item[{i}] missing published"
        # #43 thin-skip: empty description would insert 0.
        # artnet 10/10 and macrumors 20/20
        # were 100% nonempty this probe.
        # quillette is 13/15 — two Claire's
        # Weekly Letter items have empty
        # description and are thin-skipped;
        # 13 insertable is still KEEP.
        nonempty = 0
        for item in items:
            if _item_description(item):
                nonempty += 1
        if source_id == "quillette":
            assert nonempty >= 10, (
                f"{source_id} nonempty {nonempty}/{len(items)} below KEEP"
            )
        else:
            assert nonempty == len(items), (
                f"{source_id} empty description: "
                f"{len(items) - nonempty}/{len(items)}"
            )
            assert nonempty >= 10, (
                f"{source_id} nonempty {nonempty}/{len(items)} below KEEP"
            )


def test_gizmodo_hard_swapped_to_smithsonian_mag():
    """Product lock: gizmodo is gone; smithsonian_mag is the KEEP replacement."""
    by_id = {s.id: s for s in SOURCES}
    assert "gizmodo" not in by_id
    assert "gizmodo_com" not in by_id
    assert "smithsonian_mag" in by_id
    source = by_id["smithsonian_mag"]
    assert source.role == "primary"
    assert source.name == "Smithsonian Magazine"
    assert source.feed_url == (
        "https://www.smithsonianmag.com/rss/latest_articles/"
    )
    assert source.category == "综合"
    assert "https://gizmodo.com/feed" not in {s.feed_url for s in SOURCES}
    assert "https://gizmodo.com/feed/" not in {s.feed_url for s in SOURCES}
    assert "https://feeds.feedburner.com/gizmodo" not in {
        s.feed_url for s in SOURCES
    }
    assert "https://feeds.feedburner.com/Gizmodo" not in {
        s.feed_url for s in SOURCES
    }
    assert "https://www.smithsonianmag.com/rss/articles/" not in {
        s.feed_url for s in SOURCES
    }
    assert "cnet" in by_id
    assert "9to5mac" in by_id
    assert "new_yorker" in by_id
    assert by_id["new_yorker"].feed_url == (
        "https://www.newyorker.com/feed/everything"
    )


