def test_thedrive_venturebeat_navalnews_feeds_live_http_200():
    """Hit the three batch89 feeds with the same headers fetch_source sends (not stubs)."""
    by_id = {s.id: s for s in SOURCES}
    # thedrive 9/9 and venturebeat 7/7
    # are product-hung KEEP in the
    # 5–9 band (live ≥5). navalnews
    # 10/10 is the ≥10 KEEP floor.
    keep_floor = {
        "thedrive": 5,
        "venturebeat": 5,
        "navalnews": 10,
    }
    for source_id in _THEDRIVE_VENTUREBEAT_NAVALNEWS_PRIMARY:
        source = by_id[source_id]
        request = urllib.request.Request(source.feed_url, headers=RSS_HEADERS)
        try:
            with urllib.request.urlopen(request, timeout=30) as resp:
                status = resp.status
                body = resp.read()
        except urllib.error.HTTPError as exc:
            raise AssertionError(
                f"{source_id} {source.feed_url} HTTP {exc.code} with RSS_HEADERS"
            ) from exc
        assert status == 200, f"{source_id} HTTP {status}"
        assert body, f"{source_id} empty body"
        root = ET.fromstring(_decode_feed_body(body))
        items = _feed_items(root)
        count = len(items)
        assert count > 0, f"{source_id} parsed 0 items (bytes={len(body)})"
        # Required: parseable title / url / published on each item.
        # RSS 2.0 (thedrive /
        # venturebeat / navalnews)
        # uses the un-namespaced
        # element text.
        for i, item in enumerate(items):
            title = _item_title(item)
            url = _item_link(item)
            published = _item_published(item)
            assert title, f"{source_id} item[{i}] missing title"
            assert url, f"{source_id} item[{i}] missing url"
            assert published, f"{source_id} item[{i}] missing published"
        # #43 thin-skip: empty description would insert 0.
        # thedrive 9/9, venturebeat
        # 7/7, and navalnews 10/10
        # were 100% nonempty this
        # probe. ingest cap 30 still
        # KEEP.
        # thedrive MUST stay on /feed
        # (no trailing slash).
        # venturebeat MUST stay on
        # Feedburner /venturebeat/SZYF
        # (do not invent
        # venturebeat.com/feed).
        # navalnews MUST keep the
        # trailing slash on /feed/.
        nonempty = 0
        for item in items:
            if _item_description(item):
                nonempty += 1
        assert nonempty == len(items), (
            f"{source_id} empty description: "
            f"{len(items) - nonempty}/{len(items)}"
        )
        floor = keep_floor[source_id]
        assert nonempty >= floor, (
            f"{source_id} nonempty {nonempty}/{len(items)} below KEEP floor {floor}"
        )


